def _split_h2_sections(plan_text: str):
    """按 `## ` 二级标题切分，返回 [(title, content_lines)]，title 为标题文本（不含 ##），
    第一个 ## 之前的内容归入 ('', 前置行)。代码块内的 `## ` 不切分。"""
    lines = (plan_text or "").split("\n")
    sections = []
    cur_title = ""
    cur_lines = []
    in_code = False
    for ln in lines:
        if ln.strip().startswith("```"):
            in_code = not in_code
            cur_lines.append(ln)
            continue
        if not in_code and re.match(r"^##\s+", ln):
            if cur_lines or cur_title:
                sections.append((cur_title, cur_lines))
            cur_title = re.sub(r"^##\s+", "", ln).strip()
            cur_lines = []
            continue
        cur_lines.append(ln)
    if cur_lines or cur_title:
        sections.append((cur_title, cur_lines))
    return sections


_CONSTRAINT_WORDS = ("必须", "禁止", "不得", "仅限", "底线", "严禁", "只能", "务必")


def _trim_foreword(text: str, soft_limit: int = 600) -> str:
    """前因后果：按句过滤——含约束关键词的句子一律保留，其余背景句在超软上限时截断。"""
    text = text.strip()
    if len(text) <= soft_limit:
        return text
    # 按中文/英文句末切句
    parts = re.split(r"(?<=[。！？\.\!\?])", text)
    kept = []
    total = 0
    for sent in parts:
        has_constraint = any(w in sent for w in _CONSTRAINT_WORDS)
        if has_constraint or total < soft_limit:
            kept.append(sent)
            total += len(sent)
    out = "".join(kept).strip()
    if len(out) < len(text):
        out += "\n...（前置背景已截断，含约束的句子已保留）"
    return out


def _trim_code_blocks(text: str, max_lines: int = 10) -> str:
    """现状与证据：每个 fenced code block 最多保留前 max_lines 行，其余以省略提示替代。"""
    out = []
    in_code = False
    code_count = 0
    for ln in text.split("\n"):
        if ln.strip().startswith("```"):
            if not in_code:
                in_code = True
                code_count = 0
                out.append(ln)
            else:
                in_code = False
                out.append(ln)
            continue
        if in_code:
            code_count += 1
            if code_count <= max_lines:
                out.append(ln)
            elif code_count == max_lines + 1:
                out.append("...（代码块超长，仅保留前 %d 行）" % max_lines)
            continue
        out.append(ln)
    return "\n".join(out)


def _extract_core_for_review(plan_text: str):
    """有损抽取核心段送审：前因后果(按句过滤)/现状与证据(代码块截断)/实施方案/验证计划/设计/方案。
    fail-safe：缺'实施方案'或'验证计划'标题、或抽取为空 → 退化为送原计划全文。
    返回 (text_to_send, extracted_bool)。"""
    text = plan_text or ""
    sections = _split_h2_sections(text)
    titles = [t for t, _ in sections]
    if not any("实施方案" in t for t in titles) or not any("验证计划" in t for t in titles):
        return text, False  # fail-safe: 关键段缺失，送全文
    core = []
    for title, body_lines in sections:
        body = "\n".join(body_lines).strip("\n")
        if "前因后果" in title:
            core.append("## %s\n%s" % (title, _trim_foreword(body)))
        elif "现状与证据" in title:
            trimmed = _trim_code_blocks(body)
            if len(trimmed) > 1000:
                trimmed = trimmed[:1000] + "\n...（现状与证据过长，已截断）"
            core.append("## %s\n%s" % (title, trimmed))
        elif any(k in title for k in ("实施方案", "验证计划", "设计", "方案")):
            core.append("## %s\n%s" % (title, body))  # 完整保留，绝不截断
        # 其余段（背景科普/风险回滚等）丢弃
    extracted = "\n\n".join(x for x in core if x.strip())
    if not extracted.strip():
        return text, False
    return extracted, True
